package com.kisanmitra.listing;
import com.kisanmitra.user.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/listings") @RequiredArgsConstructor
public class ListingController {
 private final ListingRepository listings; private final UserRepository users;
 @GetMapping public Map<String,Object> get(@RequestParam(required=false) String status,@RequestParam(required=false) String district,@RequestParam(required=false) String category,@RequestParam(required=false) String subCategory,@RequestParam(required=false) String transactionType){var data=status==null?listings.findByStatusOrderByCreatedAtDesc("active"):listings.findByStatusOrderByCreatedAtDesc(status); data=data.stream().filter(l->district==null||district.isBlank()||district.equalsIgnoreCase(l.getDistrict())).filter(l->category==null||category.isBlank()||category.equalsIgnoreCase(l.getCategory())).filter(l->subCategory==null||subCategory.isBlank()||subCategory.equalsIgnoreCase(l.getSubCategory())).filter(l->transactionType==null||transactionType.isBlank()||transactionType.equalsIgnoreCase(l.getTransactionType())).toList(); return Map.of("success",true,"data",Map.of("listings",data,"total",data.size(),"page",1,"pages",1));}
 @GetMapping("/{id}") public ResponseEntity<?> one(@PathVariable UUID id){return listings.findById(id).<ResponseEntity<?>>map(l->ResponseEntity.ok(Map.of("success",true,"data",l))).orElseGet(()->ResponseEntity.notFound().build());}
 @GetMapping("/me") public Map<String,Object> mine(org.springframework.security.core.Authentication a){ if(a==null||!(a.getPrincipal() instanceof User u)) throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED); return Map.of("success",true,"data",listings.findBySellerIdOrderByCreatedAtDesc(u.getId())); }
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object> body,org.springframework.security.core.Authentication a){ if(a==null||!(a.getPrincipal() instanceof User u)) throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED); Listing l=new Listing(); l.setSeller(u); l.setTitle((String)body.getOrDefault("title","")); l.setDescription((String)body.getOrDefault("description","")); l.setCategory((String)body.getOrDefault("category","materials")); l.setSubCategory((String)body.getOrDefault("subCategory","")); l.setTransactionType((String)body.getOrDefault("transactionType","sell")); l.setPrice(((Number)body.getOrDefault("price",0)).doubleValue()); l.setQuantity(((Number)body.getOrDefault("quantity",0)).doubleValue()); l.setUnit((String)body.getOrDefault("unit","KG")); l.setNegotiable(Boolean.TRUE.equals(body.getOrDefault("negotiable",true))); if(body.get("images") instanceof List<?> imgs) l.setImages(imgs.stream().map(String::valueOf).toList()); if(body.get("location") instanceof Map<?,?> loc){ Object state=loc.get("state"), district=loc.get("district"), taluka=loc.get("taluka"), village=loc.get("village"); l.setState(state==null?"":String.valueOf(state)); l.setDistrict(district==null?"":String.valueOf(district)); l.setTaluka(taluka==null?"":String.valueOf(taluka)); l.setVillage(village==null?"":String.valueOf(village)); } l.setStatus("active"); return ResponseEntity.status(201).body(Map.of("success",true,"data",listings.save(l))); }
 @DeleteMapping("/{id}") public Map<String,Object> delete(@PathVariable UUID id,org.springframework.security.core.Authentication a){ var l=listings.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND)); if(a==null||!(a.getPrincipal() instanceof User u)||!l.getSeller().getId().equals(u.getId())) throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN); listings.delete(l); return Map.of("success",true,"message","Listing deleted"); }
}
